WebhookEndpoint.CreatedExactlyWhenRevise.source:
(s) =>
			[
				[s.status === "", s.definition_revision === 0, s.secret_revision === 0, s.url === ""].every(
					(ok) => ok,
				),
				[s.status !== "", s.definition_revision >= 1, s.secret_revision >= 1, s.url !== ""].every(
					(ok) => ok,
				),
			].some((ok) => ok)

WebhookEndpoint.StaleOrInactiveOutcomeIg.source:
({ before, after, command }) => {
			if (command._tag !== "RecordWebhookOutcome") {
				return true
			}
			return [
				[
					before.status === "active",
					command.definition_revision === before.definition_revision,
				].every((ok) => ok),
				[
					after.status === before.status,
					after.failure_window_started_at === before.failure_window_started_at,
					after.last_failure_at === before.last_failure_at,
					after.consecutive_failures === before.consecutive_failures,
				].every((ok) => ok),
			].some((ok) => ok)
		}

WebhookEndpoint.RedirectImmediatelyDisab.source:
({ before, after, command }) => {
			if (command._tag !== "RecordWebhookOutcome") {
				return true
			}
			return [
				before.status !== "active",
				command.definition_revision !== before.definition_revision,
				command.outcome !== "redirect",
				after.status === "disabled_redirect",
			].some((ok) => ok)
		}

WebhookEndpoint.SustainedFailureDisables.source:
({ before, after, command }) => {
			if (command._tag !== "RecordWebhookOutcome") {
				return true
			}
			return [
				before.status !== "active",
				command.definition_revision !== before.definition_revision,
				command.outcome !== "failed",
				after.status === "disabled_sustained_failure",
				after.last_failure_at - after.failure_window_started_at <
					SUSTAINED_FAILURE_DISABLE_WINDOW_MS,
			].some((ok) => ok)
		}

WebhookEndpoint.StaleSecretExpiryLeavesP.source:
({ before, after, command }) => {
			if (command._tag !== "ExpirePreviousWebhookSecret") {
				return true
			}
			return [
				command.for_revision === before.secret_revision,
				[
					after.previous_secret_revision === before.previous_secret_revision,
					after.previous_secret_expires_at === before.previous_secret_expires_at,
				].every((ok) => ok),
			].some((ok) => ok)
		}

WebhookEndpoint.UpdateKeepsWhatItDoesNot.source:
({ before, after, command }) => {
			if (command._tag !== "UpdateWebhookEndpoint") {
				return true
			}
			return [
				after.url === (command.url === null ? before.url : command.url),
				after.description ===
					(command.description === null ? before.description : command.description),
				after.event_types ===
					(command.event_types === null ? before.event_types : command.event_types),
				after.status === (command.reactivate ? "active" : before.status),
			].every((ok) => ok)
		}

WebhookEndpoint.PredatingSuccessLeavesFa.source:
({ before, after, command }) => {
			if (command._tag !== "RecordWebhookOutcome") {
				return true
			}
			return [
				before.status !== "active",
				command.definition_revision !== before.definition_revision,
				command.outcome !== "delivered",
				before.failure_window_started_at === 0,
				command.observed_at >= before.failure_window_started_at,
				[
					after.failure_window_started_at === before.failure_window_started_at,
					after.last_failure_at === before.last_failure_at,
					after.consecutive_failures === before.consecutive_failures,
				].every((ok) => ok),
			].some((ok) => ok)
		}

WebhookEndpoint.ActiveGracePeriodNotOver.source:
({ before, after, command }) => {
			if (command._tag !== "RotateWebhookSecret") {
				return true
			}
			return [
				before.previous_secret_revision === 0,
				command.rotated_at >= before.previous_secret_expires_at,
				[
					after.secret_revision === before.secret_revision,
					after.previous_secret_revision === before.previous_secret_revision,
					after.previous_secret_salt === before.previous_secret_salt,
					after.previous_secret_expires_at === before.previous_secret_expires_at,
				].every((ok) => ok),
			].some((ok) => ok)
		}
